      'cache_type' => 0,
      'snippet' => '                    <div id="msProduct" class="item-block" itemscope itemtype="http://schema.org/Product">
                    <form class="form-horizontal ms2_form" method="post">
                    <input type="hidden" name="id" value="[[*id]]" />
                        <div class="row">
                            <div class="col-md-12">
                                <div class="top">
                                    <div class="item-img col-md-6">
                                       [[!msGallery]]
                                    </div>
                                    <div class="item-info col-md-6">
                                        <div class="item-title" itemprop="name">[[*pagetitle]]</div>
                                        
                                        <div itemprop="offers" itemscope itemtype="http://schema.org/Offer">
                                             
                                        <div class="item-price" itemprop="price"> <!-- <span class="old_price">[[+old_price]] руб</span> --> [[!+price]] руб</div>

                                         <meta itemprop="priceCurrency" content="RUB">
                                        
                                        [[If?
                                            &subject=`[[+remains]]`
                                            &operator=`GT`
                                            &operand=`0`
                                            &then=`
                                            <div class="item-order">
                                            <div class="number"> 
                                                <input type="number" name="count" id="product_price" class="input-sm form-control" value="1" min="0" max="10" > 
                                            </div>
                                            <button type="submit" class="item-go" name="ms2_action" value="cart/add"> [[%ms2_frontend_add_to_cart]]</button>
                                            <div class="item-remains"><b>В наличии:</b> [[+remains]] шт.</div>
                                            <link itemprop="availability" href="http://schema.org/InStock">
                                            </div>
                                            `
                                            &else=`
                                            <div class="item-order">
                                            <div class="number"> 
                                                <input type="hidden" name="count" id="product_price" class="input-sm form-control" value="1" min="0" max="[[+remains]]" > 
                                            </div>
                                            <button type="submit" class="item-go disable" name="ms2_action" value="cart/add"> [[%ms2_frontend_add_to_cart]]</button>
                                            <div class="item-remains" style="color: red;">Нет в наличии </div>
                                            </div>
                                            `
                                        ]]
                                        
                                    </div>

                                    <div class="item-info item-info-text col-md-12" style="padding-left: 0;">

										  <!-- Nav tabs -->
										  <ul class="nav nav-tabs " role="tablist" id="tabs">
										    <li role="presentation" class="active"><a href="#about" aria-controls="about" role="tab" data-toggle="tab">О товаре</a></li>
										    <li role="presentation"><a href="#delivery-item" aria-controls="delivery-item" role="tab" data-toggle="tab">Доставка</a></li>
										    <li role="presentation"><a href="#sales-item" aria-controls="sales-item" role="tab" data-toggle="tab">Скидки</a></li>
										  </ul>

										  <!-- Tab panes -->
										  <div class="tab-content">
												    <div role="tabpanel" class="tab-pane active item-info-text-item" id="about" >
				                                        <ul>
				                                            <li><b>Страна:</b> [[+made_in]]</li>
				                                            <li><b>Номинал:</b> [[+nominal]]</li>
				                                            <li><b>Год:</b> [[+year]]</li>
				                                            <li><b>Металл:</b> [[+metal]]</li>
				                                            <li><b>Тематика:</b> [[!msOptions?
                                                                                    &name=`theme`
                                                                                    &tplOuter=`@INLINE [[+rows]]`
                                                                                    &tplRow=`@INLINE [[+value]]`
                                                                                    &outputSeparator=`, `
                                                                                    ]]</li>
                                                                                    				                                            
                                                            <li itemprop="description"><b>Описание:</b> [[*content]]</li>
				                                            <li><b>Артикул:</b> [[+article]]</li>
				                                        </ul>
												    </div>
												    <div role="tabpanel" class="tab-pane item-info-text-item" id="delivery-item">
												       [[pdoField?
                                                            &id=`2171`
                                                            &field=`content`
                                                        ]]
												    </div>
												    <div role="tabpanel" class="tab-pane item-info-text-item" id="sales-item">                     
                                                       [[pdoField?
                                                            &id=`2172`
                                                            &field=`content`
                                                        ]]
												    </div>
										  </div>
                                        </div>
                                    </div>
                                </div>

                            </div>
                        </div> 
					</form>
                    </div>
',
