// Processing rows
$output = array();
if (!empty($rows) && is_array($rows)) {
    $q = $modx->newQuery(\'modPluginEvent\', array(\'event:IN\' => array(\'msOnGetProductPrice\',\'msOnGetProductWeight\')));
    $q->innerJoin(\'modPlugin\', \'modPlugin\', \'modPlugin.id = modPluginEvent.pluginid\');
